import type { DebugDraft } from './draft';
import type { DebugParameter } from './types';

/** Reconciles declared parameter rows while retaining user-added rows and edited values.
 * @param current Editable rows currently displayed.
 * @param previous Rows generated by the previous document.
 * @param next Rows generated by the refreshed document.
 * @param ignoreCase Whether names are case-insensitive HTTP headers.
 * @returns Rows matching the new declarations plus surviving custom rows.
 */
export const reconcileParameters = (
  current: DebugParameter[],
  previous: DebugParameter[],
  next: DebugParameter[],
  ignoreCase = false,
): DebugParameter[] => {
  const key = (name: string) => (ignoreCase ? name.toLowerCase() : name);
  const oldRows = new Map(previous.map((row) => [key(row.name), row]));
  const newRows = new Map(next.map((row) => [key(row.name), row]));
  const result = current.flatMap((row) => {
    const old = oldRows.get(key(row.name));
    const replacement = newRows.get(key(row.name));
    if (!old) return [row];
    if (!replacement) return [];
    return [
      {
        ...replacement,
        ...row,
        name: replacement.name,
        value: row.value === old.value ? replacement.value : row.value,
      },
    ];
  });
  for (const row of next) {
    // An explicitly removed existing row stays removed; newly declared rows are initialized.
    if (!oldRows.has(key(row.name)) && !result.some((item) => key(item.name) === key(row.name)))
      result.push(row);
  }
  return result;
};

/** Recognizes JSON objects for property-level document reconciliation.
 * @param value Parsed JSON value.
 * @returns Whether the value has named properties rather than array elements.
 */
const isObject = (value: unknown): value is Record<string, unknown> =>
  value !== null && typeof value === 'object' && !Array.isArray(value);

/** Merges new generated JSON structure into user input without guessing renamed fields.
 * @param current Parsed user input.
 * @param previous Previously generated example.
 * @param next Newly generated example.
 * @returns Updated structure preserving edits and custom properties.
 */
const reconcileJson = (current: unknown, previous: unknown, next: unknown): unknown => {
  if (JSON.stringify(current) === JSON.stringify(previous)) return next;
  if (isObject(current) && isObject(previous) && isObject(next)) {
    const result = Object.fromEntries(
      Object.entries(current).flatMap(([key, value]) => {
        if (!Object.hasOwn(previous, key)) return [[key, value]];
        if (!Object.hasOwn(next, key)) return [];
        return [[key, reconcileJson(value, previous[key], next[key])]];
      }),
    );
    for (const [key, value] of Object.entries(next)) {
      if (!Object.hasOwn(previous, key) && !Object.hasOwn(result, key)) {
        Object.defineProperty(result, key, {
          value,
          enumerable: true,
          writable: true,
          configurable: true,
        });
      }
    }
    return result;
  }
  if (
    Array.isArray(current) &&
    Array.isArray(previous) &&
    Array.isArray(next) &&
    previous.length &&
    next.length
  ) {
    return current.map((item, index) =>
      reconcileJson(item, previous[index] ?? previous[0], next[index] ?? next[0]),
    );
  }
  return current;
};

/** Reconciles request inputs after a background OpenAPI update.
 * @param current Current draft, including user edits.
 * @param previous Defaults produced by the previous document.
 * @param next Defaults produced by the new document.
 * @returns Updated rows and body; invalid JSON or custom non-JSON text remains untouched.
 */
export const reconcileDraft = (
  current: DebugDraft,
  previous: DebugDraft,
  next: DebugDraft,
): DebugDraft => {
  let body = current.body;
  if (body === previous.body) body = next.body;
  else if (previous.body !== next.body) {
    try {
      const parsed = JSON.parse(body);
      const updated = reconcileJson(parsed, JSON.parse(previous.body), JSON.parse(next.body));
      if (JSON.stringify(parsed) !== JSON.stringify(updated))
        body = JSON.stringify(updated, null, 2);
    } catch {
      /* Preserve custom text and partially edited JSON instead of discarding input. */
    }
  }
  return {
    body,
    headers: reconcileParameters(current.headers, previous.headers, next.headers, true),
    pathParams: reconcileParameters(current.pathParams, previous.pathParams, next.pathParams),
    queryParams: reconcileParameters(current.queryParams, previous.queryParams, next.queryParams),
    formFields: reconcileParameters(current.formFields, previous.formFields, next.formFields),
    urlEncodedFields: reconcileParameters(
      current.urlEncodedFields,
      previous.urlEncodedFields,
      next.urlEncodedFields,
    ),
  };
};
